     * <p>This version adds robust validation to prevent infinite loops,
     * out‑of‑bounds writes and unexpected end‑of‑stream conditions that could
     * otherwise be exploited for a denial‑of‑service attack.</p>
     *
     * @param in  the source stream (must not be {@code null})
     * @param out the destination buffer (must not be {@code null})
     * @throws IOException if the input is malformed, ends prematurely, or would
     *                     write beyond {@code out}'s length
     */
    private static void decompress(final InputStream in, final byte[] out) throws IOException {
        if (in == null) {
            throw new NullPointerException("InputStream 'in' must not be null");
        }
        if (out == null) {
            throw new NullPointerException("Output buffer 'out' must not be null");
        }

        int position = 0;
        final int total = out.length;

        while (position < total) {
            int n = in.read();                     // read the control byte
            if (n == -1) {
                throw new IOException("Unexpected end of stream while reading control byte");
            }

            // A control byte of 0 would cause no progress; treat it as malformed.
