/**
 * Performs the JPEG "extend" operation which converts the raw
 * magnitude bits {@code v} (read from the bit‑stream) into a
 * signed integer according to the JPEG specification.
 *
 * <p>The original implementation used a {@code while} loop that
 * recomputed {@code vt} on each iteration, which could never
 * satisfy the exit condition for crafted inputs and resulted in
 * an infinite loop (Denial‑of‑Service). The correct algorithm
 * requires only a single conditional adjustment.</p>
 *
 * @param v the raw magnitude value (0 ≤ v < 2^t)
 * @param t the number of bits that were read (t ≥ 0)
 * @return the signed integer value represented by the {@code t}
 *         bits
 */
private int extend(int v, int t) {
    // No bits → value is defined as 0
    if (t <= 0) {
        return 0;
    }

    // Guard against illegal shift counts (Java shifts mask the lower 5 bits)
    // Values larger than 31 would wrap around and produce incorrect results.
    if (t > 31) {
        t = 31;
    }

    // vt = 2^(t‑1) – the smallest positive value representable with t bits
    int vt = 1 << (t - 1);

    // If the most‑significant bit is 0 the number is negative and must be
    // sign‑extended. The JPEG spec defines the correction as:
    //   v = v + (-1 << t) + 1
    if (v < vt) {
        v += (-1 << t) + 1;
    }

    return v;
}
