 * {@code javax.servlet.include.context_path} request attribute, which could be
 * manipulated to bypass security checks. The new implementation:
 *
 * <ul>
 *   <li>Decodes and cleans the raw context path using {@code decodeAndCleanUriString}.</li>
 *   <li>Normalises the path to eliminate any {@code "/./"} or {@code "/../"} segments.</li>
 *   <li>Validates the resulting path against a strict whitelist pattern.</li>
 *   <li>Ignores a potentially tampered {@code INCLUDE_CONTEXT_PATH_ATTRIBUTE} unless it
 *       matches the validated request context path.</li>
 *   <li>Ensures the root context is represented by an empty string, never {@code "/"}
 *       (which some containers incorrectly return for includes).</li>
 * </ul>
 *
 * These measures prevent an attacker from influencing routing or filter logic by
 * supplying a crafted context path.
 */
public class WebUtils {

    public static final String INCLUDE_CONTEXT_PATH_ATTRIBUTE = "javax.servlet.include.context_path";

    /** Logger for security‑relevant events. */
    private static final Logger logger = Logger.getLogger(WebUtils.class.getName());

    /** Allowed characters for a servlet context path (e.g. "/my-app"). */
    private static final Pattern VALID_CONTEXT_PATH = Pattern.compile("^(/[A-Za-z0-9._-]+)?$");

