import org.apache.logging.log4j.LogManager;
import org.apache.logging.log4j.Logger;
import java.util.Locale;
import java.util.regex.Pattern;

/**
 * Interceptor that resolves the locale from a request parameter.
 *
 * The original implementation accepted any string and passed it directly to
 * {@link LocalizedTextUtil#localeFromString(String, Locale)}.  An attacker could
 * supply a crafted value containing characters that, when later rendered in a
 * view, could lead to reflected XSS (e.g. "<script>…</script>").  The patched
 * version validates the input against a strict whitelist of locale formats
 * before constructing a {@link Locale} instance.
 */
public class I18nInterceptor extends AbstractInterceptor {

    protected static final Logger LOG = LogManager.getLogger(I18nInterceptor.class);

    /** Acceptable locale strings: "en", "en_US", "en-US", "fr", etc. */
    private static final Pattern LOCALE_PATTERN = Pattern.compile("^[a-zA-Z]{2,3}([_-][a-zA-Z]{2,3})?$");

    // -----------------------------------------------------------------------
    // other methods
    // -----------------------------------------------------------------------

    /**
     * Creates a {@link Locale} object from the request parameter, which might
     * already be a {@link Locale} or a {@link String}.  The input is validated
     * against a whitelist to prevent injection of malicious content.
     *
     * @param requestedLocale the parameter from the request
     * @return a {@link Locale} instance if the input is valid; {@code null}
     *         otherwise.
     */
    protected Locale getLocaleFromParam(Object requestedLocale) {
        if (requestedLocale == null) {
            return null;
        }

        Locale locale = null;

        // -------------------------------------------------------------------
        // 1) Parameter is already a Locale – validate its language tag.
        // -------------------------------------------------------------------
        if (requestedLocale instanceof Locale) {
            Locale candidate = (Locale) requestedLocale;
            // Build a string representation that matches the whitelist format.
            String candidateStr = candidate.toString(); // e.g. "en_US"
            if (isValidLocaleString(candidateStr)) {
                locale = candidate;
            } else {
                LOG.warn("Rejected Locale object with invalid format: {}", candidateStr);
            }
        }
        // -------------------------------------------------------------------
        // 2) Parameter is a String – validate before conversion.
        // -------------------------------------------------------------------
        else {
            String localeStr = requestedLocale.toString().trim();

            if (isValidLocaleString(localeStr)) {
                // LocalizedTextUtil.localeFromString is retained because it
                // correctly handles both "en" and "en_US"/"en-US" forms.
                locale = LocalizedTextUtil.localeFromString(localeStr, null);
                if (locale == null) {
                    LOG.warn("Locale string passed validation but could not be parsed: {}", localeStr);
                }
            } else {
                LOG.warn("Rejected locale parameter with invalid format: {}", localeStr);
            }
        }

        if (locale != null) {
            LOG.debug("Applied request locale: {}", locale);
        }

        return locale;
    }

    /**
     * Checks whether a locale string conforms to the allowed pattern.
     *
     * @param localeStr the locale string to validate
     * @return {@code true} if the string matches the whitelist; {@code false}
     *         otherwise.
     */
    private static boolean isValidLocaleString(String localeStr) {
        // Reject null or empty strings early.
        if (localeStr == null || localeStr.isEmpty()) {
            return false;
        }
        // The pattern only permits letters and a single optional separator
        // ('_' or '-') followed by more letters.  This eliminates characters
        // such as '<', '>', '/', '\\', etc., that could be used for XSS.
        return LOCALE_PATTERN.matcher(localeStr).matches();
    }

