public Calendar ceil(Calendar cal) {
    Calendar twoYearsFuture = (Calendar) cal.clone();
    twoYearsFuture.add(Calendar.YEAR, 2);
    final int MAX_ITERATIONS = 10000; // safe upper bound
    int iterations = 0;
    long previousTime = cal.getTimeInMillis();

    OUTER:
    while (true) {
        if (iterations++ > MAX_ITERATIONS) {
            throw new RareOrImpossibleDateException("Exceeded max iterations while computing ceil");
        }
        if (cal.compareTo(twoYearsFuture) > 0) {
            throw new RareOrImpossibleDateException();
        }

        for (CalendarField f : CalendarField.ADJUST_ORDER) {
            int cur = f.valueOf(cal);
            int next = f.ceil(this, cur);
            if (cur == next) {
                continue;
            }
            for (CalendarField l = f.lowerField; l != null; l = l.lowerField) {
                l.clear(cal);
            }
            if (next < 0) {
                f.rollUp(cal, 1);
                f.setTo(cal, f.first(this));
                continue OUTER;
            } else {
                f.setTo(cal, next);
                if (f.redoAdjustmentIfModified) {
                    continue OUTER;
                }
            }
        }

        // Ensure progress: if no time advancement, break to avoid infinite loop
        long currentTime = cal.getTimeInMillis();
        if (currentTime <= previousTime) {
            // No forward progress, treat as impossible/rare
            throw new RareOrImpossibleDateException("No forward progress while computing ceil");
        }
        return cal;
    }
}

