public class XPathBuilder extends ServiceSupport implements Expression, Predicate, NamespaceAware {

    private final ThreadLocal<Exchange> exchange = new ThreadLocal<Exchange>();
    private volatile Class<?> documentType = Document.class;

    // -------------------------------------------------------------------------
    //  Secure document handling
    // -------------------------------------------------------------------------

    /**
     * Returns a document (or other representation) from the given body while
     * protecting against XXE attacks.
     *
     * @param exchange the current exchange
     * @param body     the message body
     * @return a {@link Document}, {@link InputSource} or the original body,
     *         depending on the configured {@code documentType}
     * @throws Exception if a conversion error occurs
     */
    protected Object doGetDocument(Exchange exchange, Object body) throws Exception {
        if (body == null) {
            return null;
        }

        Object answer = null;
        Class<?> type = getDocumentType();
        Exception cause = null;

        // -----------------------------------------------------------------
        //  1. When a Document is requested we parse the XML ourselves using a
        //     securely configured DocumentBuilderFactory. This eliminates the
        //     possibility of external entity expansion.
        // -----------------------------------------------------------------
        if (type != null && Document.class.isAssignableFrom(type)) {
            // If the body is already a Document we can return it directly.
            if (body instanceof Document) {
                return body;
            }

            // Obtain an InputStream for the XML payload.
            InputStream is = null;
            try {
                if (body instanceof InputStream) {
                    is = (InputStream) body;
                } else if (body instanceof WrappedFile) {
                    is = exchange.getContext().getTypeConverter()
                                 .convertTo(InputStream.class, exchange, body);
                } else if (body instanceof String) {
                    is = new ByteArrayInputStream(((String) body).getBytes(StandardCharsets.UTF_8));
