import java.io.IOException;
import java.io.InputStream;
import javax.xml.stream.XMLInputFactory;
import javax.xml.stream.XMLStreamException;
import javax.xml.stream.XMLStreamReader;
import com.google.refine.importers.tree.TreeImportingParserBase;

public class XmlImporter extends TreeImportingParserBase {

    // other methods ...

    /**
     * Creates a securely configured {@link XMLStreamReader} that is protected against
     * XML External Entity (XXE) attacks.
     *
     * @param inputStream the raw XML input stream (must not be {@code null})
     * @return a configured {@code XMLStreamReader}
     * @throws XMLStreamException if the underlying parser cannot be created
     * @throws IOException        if an I/O error occurs while wrapping the stream
     */
    private static final XMLStreamReader createXMLStreamReader(InputStream inputStream)
            throws XMLStreamException, IOException {

        if (inputStream == null) {
            throw new IllegalArgumentException("inputStream must not be null");
        }

        XMLInputFactory factory = XMLInputFactory.newInstance();

        /* --------------------------------------------------------------------
         * Harden the factory against XXE.
         *
         *   - SUPPORT_DTD = false  : disables DTD processing.
         *   - IS_SUPPORTING_EXTERNAL_ENTITIES = false : prevents resolution of
         *     external entities.
         *
         * Some implementations may not support these properties; we therefore
         * set them in a defensive try/catch block and ignore the exception if the
         * property is unsupported.  This guarantees that, whenever the parser
         * respects the properties, the attack vector is eliminated.
         * -------------------------------------------------------------------- */
        try {
            factory.setProperty(XMLInputFactory.SUPPORT_DTD, Boolean.FALSE);
        } catch (IllegalArgumentException | IllegalStateException ignored) {
            // Property not supported – the parser will use its defaults.
        }

        try {
            factory.setProperty(XMLInputFactory.IS_SUPPORTING_EXTERNAL_ENTITIES, Boolean.FALSE);
        } catch (IllegalArgumentException | IllegalStateException ignored) {
            // Property not supported – the parser will use its defaults.
        }

        /* --------------------------------------------------------------------
         * Preserve the original behaviour of the application while keeping the
         * factory secure.
         *
         *   - IS_COALESCING = true               : combine adjacent character data.
         *   - IS_REPLACING_ENTITY_REFERENCES = true : replace entity references with their values.
         *   - IS_NAMESPACE_AWARE = true          : ensure namespace handling (optional but safe).
         * -------------------------------------------------------------------- */
        factory.setProperty(XMLInputFactory.IS_COALESCING, Boolean.TRUE);
        factory.setProperty(XMLInputFactory.IS_REPLACING_ENTITY_REFERENCES, Boolean.TRUE);
        try {
            factory.setProperty(XMLInputFactory.IS_NAMESPACE_AWARE, Boolean.TRUE);
        } catch (IllegalArgumentException | IllegalStateException ignored) {
            // Not all factories expose this property; safe to ignore.
        }

        // The original code wrapped the stream to strip a possible XML prefix.
        // We keep that behaviour unchanged.
        return factory.createXMLStreamReader(wrapPrefixRemovingInputStream(inputStream));
    }

    // other methods ...

}
